function author(){return `<header class="author-closing"><span>abc / 写在最后</span><h1>谢谢你陪知遥走到这里</h1></header><article class="article"><p>谢谢你陪知遥查完这些床、照片和没有写完的记录。她终于知道母亲来过，也知道有人为那次来访等了很久，这些事不能互相抵消；若你愿意，可以回去看看衣铺和街坊的生活留言，那里还有几件母亲没有做完的小事，不是为了留下她，只是让她被记得更完整一些。</p><p>abc · 原创故事与网页作品。照片是为虚构事件制作的图像，文字记录以可读排版生成，不来自真实患者或案件。</p></article><section class="author-readings"><h2>已经留下的阅读记录</h2><ul class="list">${C.achievements.map(([name,fn],i)=>{const yes=fn(state);return `<li>${yes?E(name):i===4||i===11?'未完成的生活调查':'尚未显示的记录'}<small>${yes?'已达成 · '+new Date(state.achievementDates[i]).toLocaleDateString('zh-CN'):'具体真相条件暂不显示'}</small></li>`;}).join('')}</ul></section><div class="actions">${link('p15','回街坊账目')}${link('p26','回衣铺照片')}<button type="button" data-rewind>返回正式决定之前</button></div><details><summary>参考与创作说明</summary><p>阅读组织参考《逾洲往事》，人物关系与迟来的理解参考鲁迅《故乡》《风筝》的事件组织，伪装的可见行动参考《画皮》。人物、机制、文案与素材另行原创。主线不需要阅读外部资料。</p><p><a href="https://miyeji.cn/games/yu-zhou-wang-shi" target="_blank" rel="noopener noreferrer">《逾洲往事》介绍</a></p></details>`;}
function settings(){return `<header class="settings-title"><span>当前浏览器 / 本作品</span><h1>阅读设置与存档</h1></header><section class="settings-preferences"><p>偏好只保存在当前浏览器。作品不读取真实身份、联系人或摄像头。</p>${[['static','静态效果模式']].map(([k,l])=>`<p><label><input type="checkbox" data-pref="${k}" ${state.prefs[k]?'checked':''}> ${l}</label></p>`).join('')}<p>系统减少动画偏好同样有效。作品的资料不会因效果模式改变，辅助描述不会改变原件。</p></section><section class="settings-backup"><h2>进度备份</h2><div class="actions"><button type="button" id="export-save">导出存档</button><label>导入本作品存档 <input type="file" id="import-save" accept=".json,application/json"></label></div><p id="save-feedback" role="status"></p></section><section class="settings-reset"><h2>清除进度</h2><p>清除会移去本次来往记录、已读出处、个人备注与结局记录，其他作品的存档不会受影响。请先导出备份。</p><form id="reset-form"><label>输入“清除进度”再确认 <input name="confirm" autocomplete="off" required></label><button type="submit">清除本作品进度</button></form><p id="reset-feedback" role="status"></p></section>`;}
function searchPage(){const query=new URLSearchParams(location.search).get('q')||'',results=C.search(D.pages,query,state.read,state.access,state);return `<header class="search-title"><span>已出现的出处 / 全文检索</span><h1>查找已出现的材料</h1></header><form class="searchbox" action="${ROOT}search.html"><label class="sr-only" for="search-input">人名、旧地名或物件号</label><input id="search-input" name="q" value="${E(query)}" placeholder="人名、旧地名、床台号"><button type="submit">搜索</button></form><p>支持袁老师、床箱、三一二等已出现称呼。范围为公开资料、已授权附件与已经经历的联系；尚未领取的私人全文不会进入搜索结果。</p>${query&&results.length?`<ul class="list">${results.map(x=>`<li>${link(x.id,sites[x.site][0]+' · '+x.title)}<small>${E(x.date)}</small></li>`).join('')}</ul>`:query?'<p>没有匹配记录。</p>':'<p>输入要检索的文字。</p>'}${link('help','阅读帮助')}`;}
function readingTools(){return displayedPlatform()==='author'?`<nav class="private-tools">${link('notes','随身便笺')} ${link('help','帮助')} ${link('settings','存档')} </nav>`:`<nav class="personal-dock" aria-label="我的工具">${link('notes','我的便笺')}</nav>`;}

