 const entries={hotel:[['p01','首页'],['p02','客房与价格'],['hotel-directions','来店路线'],['p03','住客留言'],['p07','老店迁址'],['hotel-contact','联系前台']],forum:[['p09','街坊说事'],['p15','店铺往来'],['forum-search','搜索']],paper:[['p16','首页'],['p17','旧街报道'],['p18','更正与补刊'],['p20','街巷'],['paper-search','往期查询']],store:[['p21','接收登记'],['store-search','物件查询'],['p22','签领查询'],['p23','返库登记']],album:[['p25','全部相册'],['p26','衣铺'],['p27','旧街'],['p28','家信'],['p30','学校门口']],hospital:[['p31','患者服务'],['hospital-request','资料复制']]};
