function mailFolders(){
 const unread=receivedMail().filter(x=>x.id==='entry'?!state.notes.mailread_entry:normalMail.some(m=>m.id===x.id)?!state.notes['normalread_'+x.id]:!state.read[x.id]).length;
 return `<aside class="mail-folders"><button type="button" class="mail-write-button" data-mail-new>写　信</button><nav aria-label="邮箱文件夹">${localNav('mail-inbox','收件箱'+(unread?'　('+unread+')':''))}${localNav('mail-drafts','草稿箱')}${localNav('mail-sent','已发送')}${localNav('mail-trash','已删除草稿')}</nav><h2>文件</h2>${localNav('mail-attachments','附件管理')}<div class="mail-owner"><strong>许知遥</strong><small>个人邮箱</small></div></aside>`;
}

function nativeShell(site,html){
 const layout=D.design?.[P]?.layout||P,privateInn=site==='hotel'&&['p04','p05','p06'].includes(P);
 const main=`<main id="main" class="${site}-page document-${P} ${isCompose()?'compose-page':''} ${privateInn?'private-inn-file':''} ${!p?'support-'+P:''}" data-layout="${layout}">${p&&!isCompose()?breadcrumbs(p):''}${html}${p&&!isCompose()&&!gating(p)&&!new URLSearchParams(location.search).get('section')?dailyAddendum(p):''}</main>`;
 if(site==='message')return `<div class="mail-workspace">${mailFolders()}${main}</div>`;
 if(site==='hotel'&&!privateInn)return `<div class="hotel-site-body">${main}<aside class="hotel-service-index"><h2>住店之前</h2>${link('p02','客房与价格')}${link('hotel-directions','从新桥怎么过来')}${link('hotel-contact','问问前台')}<dl><dt>入住</dt><dd>14:00以后</dd><dt>退房</dt><dd>12:00以前</dd><dt>早餐</dt><dd>隔壁铺子自理</dd></dl><h2>前台通知</h2><p>312房暂停接单。换房或查询原入住记录，请到前台联系。</p>${link('p08','前台回复')}<h2>附近走走</h2><p>桥头早市 / 步行约5分钟<br>沿河路 / 从桥下往西</p></aside></div>`;
 if(site==='hospital')return `<div class="hospital-site-body"><aside class="patient-menu"><h2>患者服务</h2>${link('p31','资料复制须知')}${link('hospital-request','凭领取函取件')}${auxLink('p31','hours','窗口时间与交通')}${auxLink('p31','copy','副本复制与装袋')}${auxLink('p31','lost','窗口失物')}${state.access.medical?`<h2>本次领取</h2>${link('p33','护理记录')}${link('p34','收件人附页')}`:''}<p>一层资料服务窗口<br>工作日 08:00—11:30<br>14:00—17:00</p></aside>${main}</div>`;
 if(site==='phone')return `<div class="phone-workspace"><aside class="phone-directory"><h2>联系</h2>${contactNav()}</aside>${main}</div>`;
 return main;
}

