function photoHtml(id){
 const im=D.images[id];if(!im)return '<p>照片暂未取得。</p>';const site=displayedPlatform(),doc=!!im.transcript,natural={cabinet:'柜门近照',room306:'306单床房',room312:'312维修留照',facade:'新桥路店面',stairs:'三楼楼梯',window:'三楼窗向',hall:'一楼大厅',family:'一家人的合照',shop:'衣铺门口',street:'河沿路',raincoat:'留下的雨衣',patch:'门板修补处',mother:'床沿坐着的秀琴',firstperson:'木沿下面'}[id]||im.source;
 let caption='';
 if(site==='message')caption=`<span>${E(natural)}.${E(im.masterExt)}</span>　<button class="inline-button" type="button" data-zoom="${id}">查看原图</button>`;
 else if(site==='scene')caption='';
 else if(site==='album')caption=`<span>${E(natural)}</span><small>${E(im.date)}　/　玉枝上传</small>`;
 else if(site==='hotel')caption=`<span>${E(natural)}</span><small>${E(im.date)}</small>`;
 else caption=`<span>${E(im.source)}</span><small>${E(im.date)}</small>`;
 const notice=site==='scene'?'图像辅助描述':'图像文字与辅助描述';
 return `<figure class="evidence-photo photo-${site} ${doc?'document-scan':''}" data-image="${id}"><button type="button" class="photo-open" data-zoom="${id}" aria-label="查看${E(natural)}原图"><img src="${ROOT}assets/${id}.${im.ext}?v=20261012v2" alt="${E(im.alt)}" width="${im.width}" height="${im.height}" ${im.critical?'fetchpriority="high"':'loading="lazy"'} decoding="async"></button><div class="image-error" hidden><p>图片未能加载。</p><button type="button" data-retry="${id}">重新加载</button><p>${E(im.alt)}</p></div>${caption?`<figcaption>${caption}</figcaption>`:''}<details class="visual-description" data-work-ui><summary>${notice}</summary><p>${E(im.alt)}</p>${im.transcript&&im.transcript!==im.alt?`<p>${E(im.transcript)}</p>`:''}</details></figure>`;
}

