function printLeaves(page,labels){return `<div class="print-leaves">${page.images.map((id,i)=>`<section class="print-leaf"><header><span>${E(labels[i])}</span><small>${E(D.images[id].date)}</small></header>${photoHtml(id)}${para(page.body.slice(i,i+1))}</section>`).join('')}</div>`;}
function albumRolls(){return (state.drafts.album_sort==='date'?['p26','p27','p30','p28']:['p30','p26','p27','p28']).map((id,i)=>{const page=byId[id];return `<li><div class="roll-number">${id==='p28'?'家信':id==='p30'?'补洗':'0'+(i+1)}</div><div class="roll-photo">${routeAnchor(href(id),page.title,'album')}<figure><a href="${E(href(id))}" target="_self" aria-label="打开${E(page.title)}"><img src="${ROOT}assets/${page.images[0]}.${D.images[page.images[0]].ext}" width="${D.images[page.images[0]].width}" height="${D.images[page.images[0]].height}" loading="lazy" decoding="async" alt="${E(D.images[page.images[0]].alt)}"></a></figure></div><div class="roll-notes"><p>${E(({p26:'衣铺里留下的近照，雨衣的袖口还没收好。',p27:'搬走以前的河沿路，后来留在房间里的柜子。',p28:'母亲写回家的信，玉枝没有丢。',p30:'相馆的补洗章与照片拍摄日分开记。'})[id])}</p><small>${E(page.date)}</small></div></li>`;}).join('');}

