function attachmentFile(id,label){const im=D.images[id],file=id+'.'+(im.masterExt||im.ext),filename=label||({cabinet:'柜门近照',zhangLetter:'张岚的来信原件',zhangDream:'当年留存的照片'}[id])||id,size=attachmentSizes[id],sizeText=size?(size>=1048576?(size/1048576).toFixed(1)+' MB':Math.ceil(size/1024)+' KB'):'';return `<a class="attachment-file" href="${E(ROOT+'masters/'+file)}" download="${E(filename)}.${im.masterExt}">${E(filename)}.${im.masterExt}</a><span class="attachment-size"> ${E(sizeText)}</span>`;}
function mailDetailTools(reply,forward=''){
 return `<nav class="message-controls" aria-label="邮件操作">${link('mail-inbox','返回收件箱')}${reply||''}${forward?routeAnchor(href('mail-write')+'?forward='+encodeURIComponent(forward),'转发','message'):''}<button type="button" class="mail-star" data-mail-star="${E(P)}" aria-pressed="${state.notes['star_'+P]==='1'}">${state.notes['star_'+P]==='1'?'已加星标':'加星标'}</button></nav>`;
}

function entry(){
 return `${mailDetailTools(routeAnchor(href('mail-write')+'?reply=entry','回复','message'),'entry')}<header class="first-letter-title"><h1>柜子的报价还没记来处</h1><div class="mail-sender-line"><strong>陈玉枝</strong><span>发给：许知遥</span><time>2026年10月9日　14:26</time></div><details class="mail-address-detail"><summary>信件详情</summary><dl><dt>发件人</dt><dd>陈玉枝 / 站内联系人</dd><dt>收件人</dt><dd>许知遥 / 个人邮箱</dd><dt>日期</dt><dd>2026年10月9日 14:26</dd></dl></details></header><article class="first-letter"><p>知遥：</p><p>你发的那张照片我看过了，柜门下面那两道锉痕确实像你妈留下的。她那时候嫌门板总磕脚，蹲在地上磨了半天，磨完还叫你过去试，说这回不会再碰到小腿了。</p><p>不过我还没看见旧物票，不能只凭这两道痕迹就认下来。我想买下这个柜子，可他发来的报价没有记来处。沈梁说铺盖已经换新，我问的是柜子，他又拿房间照片给我看。</p><p>这是他发来的近照，我一并转给你。报价单却只有房号。</p>${photoHtml('cabinet')}<p>宾馆的${link('p02','客房页面')}我看了，还是这些家具。前台又发来${link('p06','两张票据')}，一张买铺盖，一张是搬来的木件，这两张账是分开装订的。</p><p>三卷相片与一封信我也整理好了，背面一起拍给你。${link('p25','相册放在这里')}，分享口令是<strong>蓝线袖口</strong>，不是你生日。学校门口那张后来补洗过，原底片的持有人我找到了。</p><p>这份${composeAnchor(5,'家属意见联')}我还留着，名单那边没结清。</p><p>雨衣带上。等你问完，我过来接你。</p><p class="letter-signature">玉枝</p></article><section class="mail-attachment-tray"><h2>附件（1）</h2><div><span class="attachment-type">PNG</span><p>${attachmentFile('cabinet','柜门近照')}<small>陈玉枝转来的房务照片</small></p><button type="button" data-zoom="cabinet">预览</button></div></section><div class="mail-reply-bottom">${routeAnchor(href('mail-write')+'?reply=entry','回复陈玉枝','message')}　${routeAnchor(href('mail-write')+'?forward=entry','转发','message')}</div>`;
}

