if(page.id==='p02')extra+=`<form id="room-estimate" class="room-estimate"><h2>住宿费用估算</h2><label for="room-arrival">入住日期</label><input id="room-arrival" type="date" name="arrival" required><label for="room-departure">退房日期</label><input id="room-departure" type="date" name="departure" required><button type="submit">计算</button><p id="room-estimate-feedback" role="status"></p></form>`;
if(page.id==='p14')extra+=`<form id="everyday-reply-form" data-thread="p14"><label for="everyday-reply">回复</label><textarea id="everyday-reply" data-note="forum_draft_p14" maxlength="1000" required>${E(state.notes.forum_draft_p14||state.notes.forum_post_p14||'')}</textarea><button type="submit">发表回复</button><p id="everyday-feedback" role="status"></p></form>${state.notes.forum_post_p14?`<p class="posted-reply">许知遥：${E(state.notes.forum_post_p14)}</p>`:''}`;
