function refreshFileLabel(el){if(!el?.isConnected)return;const key=el.id,f=allowedFiles(+el.closest('form').dataset.operation).find(x=>x.id===el.value)||materialFiles.find(x=>x.id===el.value);$(`[data-file-name="${key}"]`).textContent=f?.title||'';for(const attr of ['preview','remove'])$(`[data-file-${attr}="${key}"]`).hidden=!el.value;}
const filePicker=window.MYFilePicker.create({
 files:id=>{refresh();return allowedFiles(id);},
 sourceTitle:f=>byId[f.source]?.title||'',searchText:f=>f.title+' '+(byId[f.source]?.title||''),
 thumbnail:f=>f.image?`<img src="${ROOT}assets/${f.image}.${D.images[f.image].ext}" alt="" width="72" height="54">`:'<span aria-hidden="true">原件</span>',
 previewHtml:operationPreview,zoom:openZoom,
 choose:(field,file)=>{refresh();if(state.solved[+field.closest('form').dataset.operation])return false;if(!Array.from(field.options).some(o=>o.value===file.id))field.add(new Option(file.title,file.id));field.value=file.id;field.dispatchEvent(new Event('change',{bubbles:true}));refreshFileLabel(field);return true;}
});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.filePick){flushNote();filePicker.open(b);}if(b.dataset.fileRemove){const field=$('#'+b.dataset.fileRemove);if(!field)return;field.value='';field.dispatchEvent(new Event('change',{bubbles:true}));refreshFileLabel(field);$(`[data-file-pick="${field.id}"]`).focus();}if(b.dataset.filePreview){const field=$('#'+b.dataset.filePreview),v=field?.value,f=materialFiles.find(x=>x.id===v);if(!v)return;if(D.images[v]||f?.image)openZoom(f?.image||v,b);else filePicker.preview(b);}});

