function openZoom(id,from){const a=D.images[id];zoomReturn=from;zoomAsset=id;zoomScale=1;zoomScroll=scrollY;const dialog=$('#zoom');dialog.innerHTML=`<header><button type="button" id="close-zoom">关闭原图</button><button type="button" id="zoom-out" aria-label="缩小图片">－</button><button type="button" id="zoom-in" aria-label="放大图片">＋</button><button type="button" id="zoom-reset">复位</button><button type="button" id="zoom-full">全屏查看</button><span id="zoom-status" role="status">100%</span></header><div class="zoom-stage" tabindex="0"><img src="${ROOT}masters/${id}.${a.masterExt||a.ext}?v=20261012v2" alt="${E(a.alt)}"></div><p class="zoom-help">放大后触屏滑动，键盘方向键平移，加减缩放，Escape关闭。</p>`;dialog.showModal();$('#close-zoom').onclick=()=>dialog.close();$('#zoom-in').onclick=()=>setZoom(zoomScale+.25);$('#zoom-out').onclick=()=>setZoom(zoomScale-.25);$('#zoom-reset').onclick=()=>setZoom(1);$('#zoom-full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(dialog.requestFullscreen)await dialog.requestFullscreen();else $('#zoom-status').textContent='浏览器不支持全屏，可继续缩放';}catch{$('#zoom-status').textContent='全屏未获允许，可继续缩放';}};const img=dialog.querySelector('img');img.onload=()=>setZoom(1);img.onerror=()=>{img.hidden=true;const stage=$('.zoom-stage');stage.insertAdjacentHTML('beforeend',`<div class="zoom-error"><p>原图未能加载。下方保留同范围观察说明，可以返回后重试。</p><p>${E(a.alt)}</p>${a.transcript&&a.transcript!==a.alt?`<p>${E(a.transcript)}</p>`:''}</div>`);};$('#close-zoom').focus();}
function setZoom(s){zoomScale=Math.max(.5,Math.min(4,s));const stage=$('.zoom-stage'),img=stage.querySelector('img');if(!img||img.hidden)return;const width=Math.min(stage.clientWidth,img.naturalWidth||stage.clientWidth)*zoomScale;img.style.width=width+'px';$('#zoom-status').textContent=Math.round(zoomScale*100)+'%';}
document.addEventListener('keydown',e=>{if(!$('#zoom').open)return;if(e.key==='+'||e.key==='='){e.preventDefault();setZoom(zoomScale+.25);}if(e.key==='-'){e.preventDefault();setZoom(zoomScale-.25);}const arrows={ArrowLeft:[-80,0],ArrowRight:[80,0],ArrowUp:[0,-80],ArrowDown:[0,80]};if(arrows[e.key]){e.preventDefault();$('.zoom-stage').scrollBy(...arrows[e.key]);}});$('#zoom').addEventListener('close',()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});const target=zoomReturn?.isConnected?zoomReturn:filePicker.zoomTarget(zoomAsset)||$(`[data-zoom="${zoomAsset}"]`);target?.focus({preventScroll:true});window.scrollTo(0,zoomScroll);});
bindDelegates();render();const saved=state.scroll[scrollKey()]||0;requestAnimationFrame(()=>{if(saved)window.scrollTo(0,saved);});
// Essential next image starts loading independently of visible UI; failure stays observable.
if(p?.id==='p04'){const im=new Image();im.src=ROOT+'assets/room312.webp?v=20261012v2';}if(p?.id==='p05'){const index=state.pictures.p05||0,next=p.images[index+1];if(next){const im=new Image();im.src=ROOT+'assets/'+next+'.webp?v=20261012v2';}}
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');motionQuery.addEventListener?.('change',()=>{document.body.classList.toggle('static',state.prefs.static||motionQuery.matches);if(motionQuery.matches)$$('.effect-playing').forEach(x=>x.classList.remove('effect-playing'));});
window.MYAppDebug={gating,state:()=>refresh(),prefix:PREFIX};
